mapper.select:
SELECT COUNT(*)
FROM TODO_CATEGORY
WHERE USER_NUM = #{userNum}
  AND CATEGORY_NAME = #{categoryName}

mapper.insert:
INSERT INTO TODO_CATEGORY (
    TODO_CATEGORY_NUM, USER_NUM, CATEGORY_NAME, COLOR
) VALUES (
    SEQ_TODO_CATEGORY.NEXTVAL, #{user_num}, #{category_name}, #{color}
)

mapper.delete:
DELETE FROM TODO_CATEGORY
WHERE TODO_CATEGORY_NUM = #{todoCategoryNum}
  AND USER_NUM = #{userNum}

mapper.update:
UPDATE PERSONAL_TODO
SET COMPLETE = #{complete}
WHERE TODO_NUM = #{todoNum}
  AND USER_NUM = #{userNum}

UPDATE PERSONAL_TODO
SET TODO_CATEGORY_NUM = #{todo_category_num, jdbcType=NUMERIC},
    TITLE = #{title},
    CONTENT = #{content},
    DEADLINE = #{deadline, jdbcType=DATE},
    PRIORITY = #{priority}
WHERE TODO_NUM = #{todo_num}
  AND USER_NUM = #{user_num}

mapper.delete:
DELETE FROM PERSONAL_TODO
WHERE TODO_NUM = #{todoNum}
  AND USER_NUM = #{userNum}
